<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetCodeVO;

trait SnippetAssetCodeAttributeHolder
{
    protected SnippetAssetCodeVO|string|null $code = null;
    protected bool $codeAssigned = false;

    public function getCodeOrCurrent(SnippetAssetCodeVO $code): SnippetAssetCodeVO
    {
        if ($this->codeAssigned) {
            \assert(null !== $this->code);
            return SnippetAssetCodeVO::from($this->code);
        } else {
            return $code;
        }
    }
    public function codeTryBuildInitial(ConstraintFailList $error): ?SnippetAssetCodeVO
    {
        return  SnippetAssetCodeVO::tryFrom($this->codeAssigned ? $this->code : null, $error);
    }
    public function code(SnippetAssetCodeVO|string $code): static
    {
        $this->code = $code;
        $this->codeAssigned = true;
        return $this;
    }
    public function getCode(): ?string
    {
        return $this->code instanceof SnippetAssetCodeVO ? $this->code->value() : $this->code;
    }
    public function isCodeAssigned(): bool
    {
        return $this->codeAssigned;
    }
    public function writeCodeTo(mixed $att): void
    {
        if ($this->codeAssigned) {
            \assert(null !== $this->code);
            $att->code($this->code);
        }
    }
    public function readCodeFrom(mixed $att): void
    {
        if ($att->isCodeAssigned()) {
            $code = $att->getCode();
            \assert(null !== $code);
            $this->code($code);
        }
    }
    public function unsetCode(): static
    {
        $this->codeAssigned = false;
        return $this;
    }
    protected function withDefaultCode(): void
    {
    }
    protected function withAssertedCodeRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->codeAssigned = $this->codeAssigned) {
            $value->code = SnippetAssetCodeVO::tryFrom($this->code, $errorsList);
        }
    }
}
